/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg a = 0;
  wire match;
  reg [8:0] hist;
  integer i;

  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));

  always #5 clk = ~clk;

  task step(input bit din);
    begin
      a = din;
      @(posedge clk);
      hist = {hist[7:0], din};
      #1;
      if (match "'!== ((hist[8:6] == 3'"'b011) && (hist[2:0] == 3'b110))) begin
        "'$display("FAIL t=%0t hist=%b din=%b match=%b exp=%b", $time, hist, din, match, ((hist[8:6] == 3'"'b011) && (hist[2:0] == 3'b110)));
        "'$finish;
      end
    end
  endtask

  initial begin
    hist = 9'"'b0;
    repeat (2) @(posedge clk);
    rst_n = 1;

    // explicit matching sequence: 011_101_110
    step(0); step(1); step(1); step(1); step(0); step(1); step(1); step(1); step(0);

    // a few extra cycles / overlaps
    step(1); step(1); step(0); step(1); step(1); step(0); step(0); step(1); step(1); step(0);

    "'$display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

